\end{equation*}

\begin{equation*}
m_{a}=\rho_{a}V_{f}=1.293\times10^{-3}{\rm g\,cm^{-3}}\times0.272{\rm cm^{3}}
     \approx3.5\times10^{-4}{\rm g}=3.5\times10^{-7}{\rm kg}
\end{equation*}

so that the peak air kerma rate in the focal spot is

\begin{equation*}
\dot K_{a}= \frac{\dot E_{a}}{m_{a}}=
\frac{I\,W/e}{\rho_{a}A_{f}L}\approx
\frac{6.8\times10^{-11}}{3.52\times10^{-7}}\approx
1.9\!-\!2.0\times10^{-4}\ {\rm Gy\,s^{-1}}\approx0.19\ {\rm mGy\,s^{-1}}
\end{equation*}

in air.  With $(\mu_{en}/\rho)_{t}\simeq(\mu_{en}/\rho)_{a}=0.328\;{\rm
cm^{2}g^{-1}}$

\begin{equation*}
\dot D_{t}\simeq\dot K_{a}\approx1.9\times10^{-4}\ {\rm Gy\,s^{-1}}
\end{equation*}

is the entrance kerma/dose rate in soft tissue in the $0.30\times6.0\;{\rm mm^{2}}$
pencil beam, i.e.

\begin{equation*}
\dot\Phi =\frac{\dot K_{a}}{E(\mu_{en}/\rho)}\approx
1.1\times10^{8}\ {\rm ph\,cm^{-2}s^{-1}},\qquad
E=33{\rm keV}=5.29\times10^{-15}{\rm J},
\end{equation*}

at the focus.  The $50\,{\rm mm}\to0.30\,{\rm mm}$ horizontal
demagnification of the Laue fan is already contained in the measured
$2.0\,{\rm pA}$ focal current.

A material point is in the $w_{f}=0.30\,{\rm mm}$ wide pencil for the
dwell time

\begin{equation*}
t_{d}=w_{f}/v_{s}=\frac{w_{f}}{{\rm step/exposure}}\approx0.02\ {\rm s}
\end{equation*}

quoted for the horizontal raster.  Hence the dose actually received by
a surface element in one monochromatic pass is

\begin{equation*}
D_{1}= \dot D_{t}\,t_{d}\approx
